-- SELECT only. 20261126100000_drive_connection_clients 적용 뒤. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
-- expect: history recorded = 예
-- expect: new table locked = 예
-- expect: service_role grants exact = 예
-- expect: drive connections RLS on and no anon or authenticated privilege = 예
-- expect: drive connections rows = 기록
-- expect: drive connections grants policies hash = 기록
select 'history recorded' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261126100000' and name='drive_connection_clients')=1 then '예' else '아니오' end as value
union all select 'new table locked',case when to_regclass('public.app_drive_connection_clients') is not null and (select relrowsecurity from pg_class where oid=to_regclass('public.app_drive_connection_clients')) and not exists(select 1 from pg_policy where polrelid=to_regclass('public.app_drive_connection_clients')) and not has_any_column_privilege('anon','public.app_drive_connection_clients','select,insert,update,references') and not has_any_column_privilege('authenticated','public.app_drive_connection_clients','select,insert,update,references') and not has_table_privilege('anon','public.app_drive_connection_clients','delete,truncate,trigger') and not has_table_privilege('authenticated','public.app_drive_connection_clients','delete,truncate,trigger') then '예' else '아니오' end
union all select 'service_role grants exact',case when to_regclass('public.app_drive_connection_clients') is not null and has_table_privilege('service_role','public.app_drive_connection_clients','select') and has_table_privilege('service_role','public.app_drive_connection_clients','delete') and not has_table_privilege('service_role','public.app_drive_connection_clients','insert,update,truncate,references,trigger') and has_column_privilege('service_role','public.app_drive_connection_clients','oauth_client','insert,update') and not has_column_privilege('service_role','public.app_drive_connection_clients','workspace_id','update') then '예' else '아니오' end
union all select 'drive connections RLS on and no anon or authenticated privilege',case when (select relrowsecurity from pg_class where oid=to_regclass('public.app_drive_connections')) and not has_any_column_privilege('anon','public.app_drive_connections','select,insert,update,references') and not has_any_column_privilege('authenticated','public.app_drive_connections','select,insert,update,references') then '예' else '아니오' end
union all select 'drive connections rows',(select count(*)::text from public.app_drive_connections)
union all select 'drive connections grants policies hash',md5(coalesce((select c.relrowsecurity::text||':'||coalesce(c.relacl::text,'') from pg_class c where c.oid=to_regclass('public.app_drive_connections')),'')
  ||coalesce((select string_agg(a.attname::text||':'||coalesce(a.attacl::text,''),',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_drive_connections') and a.attnum>0 and not a.attisdropped),'')
  ||coalesce((select string_agg(p.polname::text,',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_drive_connections')),''));
